89	function parseAgent(filePath) {
90	  try {
91	    const content = fs.readFileSync(filePath, 'utf-8');
92	    const { data, content: body } = matter(content);
93	    const stats = fs.statSync(filePath);
94	    return {
95	      filename: path.basename(filePath, '.md'),
96	      path: filePath,
97	      frontmatter: data,
98	      name: data.name || path.basename(filePath, '.md'),
99	      description: data.description || '',
100	      model: data.model || '',
101	      tools: data.tools || '',
102	      body: body.trim(),
103	      raw: content,
104	      updatedAt: stats.mtime.toISOString(),
105	    };
106	  } catch (e) {
107	    return null;
108	  }
109	}
