144	function discoverProjects(dirs) {
145	  const projects = [];
146	  for (const dir of dirs) {
147	    const resolved = dir.replace(/^~/, HOME);
148	    if (!fs.existsSync(resolved)) continue;
149	    try {
150	      const entries = fs.readdirSync(resolved, { withFileTypes: true });
151	      for (const entry of entries) {
152	        if (!entry.isDirectory()) continue;
153	        if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
154	        const projectPath = path.join(resolved, entry.name);
155	        const hasClaudeDir = fs.existsSync(path.join(projectPath, '.claude'));
156	        const hasClaudeMd = fs.existsSync(path.join(projectPath, 'CLAUDE.md'));
157	        const hasPackageJson = fs.existsSync(path.join(projectPath, 'package.json'));
158	        const hasPubspec = fs.existsSync(path.join(projectPath, 'pubspec.yaml'));
159	        if (hasClaudeDir || hasClaudeMd || hasPackageJson || hasPubspec) {
160	          const agents = listAgents(path.join(projectPath, '.claude', 'agents'));
161	          const commands = listMdFiles(path.join(projectPath, '.claude', 'commands'));
162	          const rules = listMdFiles(path.join(projectPath, '.claude', 'rules'));
163	          projects.push({
164	            id: Buffer.from(projectPath).toString('base64url'),
165	            name: entry.name,
166	            path: projectPath,
167	            displayPath: projectPath.replace(HOME, '~'),
168	            hasClaudeDir,
169	            hasClaudeMd,
170	            agentCount: agents.length,
171	            commandCount: commands.length,
172	            ruleCount: rules.length,
173	            agents,
174	            commands: commands.map(c => c.name),
175	            rules: rules.map(r => r.name),
176	          });
177	        }
178	      }
179	    } catch {}
180	  }
181	  return projects;
182	}
