791	// Topological sort helper
792	function topoSort(nodes, edges) {
793	  const inDegree = {};
794	  const adj = {};
795	  for (const n of nodes) { inDegree[n.id] = 0; adj[n.id] = []; }
796	  for (const e of edges) {
797	    adj[e.source].push(e.target);
798	    inDegree[e.target] = (inDegree[e.target] || 0) + 1;
799	  }

