800	  const queue = nodes.filter(n => inDegree[n.id] === 0).map(n => n.id);
801	  const order = [];
802	  while (queue.length) {
803	    const id = queue.shift();
804	    order.push(id);
805	    for (const next of adj[id]) {
806	      inDegree[next]--;
807	      if (inDegree[next] === 0) queue.push(next);
808	    }
809	  }
810	  return order;
811	}
